use semio_framework_job_context::testkit;
use super::*;
#[test]fn genuine_original_loan_admission_keeps_real_alias_before_receipt_refusal(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let quantum=RetainedCloneGrant{maximum_items:1,..stock};for refuse in [false,true]{let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());let mut loan=None;caller.bare_turn(RetainedCloneGrant{maximum_items:0,..quantum},|cx|{let before=cx.fuel_remaining();assert!(!cx.original_source_parent()?.admit_loan(&mut loan,cx)?);assert_eq!(before-cx.fuel_remaining(),row["deniedWork"].as_u64().unwrap());assert!(loan.is_none());Ok(())}).unwrap();caller.bare_turn(quantum,|cx|{let before=cx.fuel_remaining();let maximum=testkit::retained_grant_mut(cx).maximum_items;testkit::set_loan_receipt_refusal(refuse);let result=cx.original_source_parent()?.admit_loan(&mut loan,cx);testkit::retained_grant_mut(cx).maximum_items=maximum;assert_eq!(before-cx.fuel_remaining(),row["admittedWork"].as_u64().unwrap());assert!(loan.is_some());assert_eq!(loan.as_ref().unwrap().source_identity()?,cx.original_source_parent()?.source_identity()?);if refuse{let failure=result.unwrap_err();assert_eq!(failure.retained_progress().copied_items,1);assert_eq!(failure.retained_progress().copied_bytes,row["copiedBytes"].as_u64().unwrap()as usize);}else{assert!(result.unwrap());}assert_eq!(serde_json::to_value(loan.is_some()).unwrap(),row["receiptRefusalRetainsLoan"]);Ok(())}).unwrap();caller.bare_turn(quantum,|cx|{let before=cx.fuel_remaining();assert!(cx.original_source_parent()?.admit_loan(&mut loan,cx)?);assert_eq!(before-cx.fuel_remaining(),row["cachedWork"].as_u64().unwrap());Ok(())}).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if loan.as_ref().unwrap().terminal_is_empty(){break}caller.bare_turn(quantum,|cx|loan.as_mut().unwrap().close_step(cx.original_source_parent()?,cx)).unwrap();}assert!(loan.as_ref().unwrap().terminal_is_empty());drop(loan);caller.retire(stock);}}
